import{St as e,at as t,it as n,st as r,t as i,vt as a}from"./chunks/framework.B8HA7oqK.js";var o=JSON.parse(`{"title":"Правила разработки","description":"","frontmatter":{},"headers":[],"relativePath":"ru/development/intro/guide.md","filePath":"ru/development/intro/guide.md","lastUpdated":1780338995000}`),s={name:`ru/development/intro/guide.md`};function c(i,o,s,c,l,u){let d=e(`Badge`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="правила-разработки" tabindex="-1">Правила разработки <a class="header-anchor" href="#правила-разработки" aria-label="Permalink to “Правила разработки”">​</a></h1><h2 id="основные-принципы" tabindex="-1">Основные принципы <a class="header-anchor" href="#основные-принципы" aria-label="Permalink to “Основные принципы”">​</a></h2><h3 id="система-контроля-версии" tabindex="-1">Система контроля версий <a class="header-anchor" href="#система-контроля-версии" aria-label="Permalink to “Система контроля версий”">​</a></h3><p>Код проекта X размещен на GitHub:</p><ul><li>Ядро Xray <a href="https://github.com/XTLS/Xray-core" target="_blank" rel="noreferrer">Xray-core</a></li><li>Скрипты установки <a href="https://github.com/XTLS/Xray-install" target="_blank" rel="noreferrer">Xray-install</a></li><li>Шаблоны конфигурации <a href="https://github.com/XTLS/Xray-examples" target="_blank" rel="noreferrer">Xray-examples</a></li><li>Документация по Xray <a href="https://github.com/XTLS/Xray-docs-next" target="_blank" rel="noreferrer">Xray-docs-next</a></li></ul><p>Вы можете использовать <a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a> для получения кода.</p><h3 id="ветки-branch" tabindex="-1">Ветки (Branch) <a class="header-anchor" href="#ветки-branch" aria-label="Permalink to “Ветки (Branch)”">​</a></h3><ul><li>Основной веткой проекта является main.</li><li>Основной веткой для выпуска релизов также является main.</li><li>Необходимо убедиться, что main в любой момент времени может быть скомпилирован и работает корректно.</li><li>Если вам нужно разработать новую функцию, создайте новую ветку для разработки. После завершения разработки и тщательного тестирования объедините ее с основной веткой.</li><li>Удалите ветки, которые были объединены с основной веткой и больше не нужны.</li></ul><h3 id="релизы-release" tabindex="-1">Релизы (Release) <a class="header-anchor" href="#релизы-release" aria-label="Permalink to “Релизы (Release)”">​</a></h3>`,9),r(d,{text:`В РАЗРАБОТКЕ`,type:`warning`}),o[1]||=t(`<ul><li>Создайте два канала выпуска: для предварительных версий и для стабильных версий. <ul><li>Предварительные версии могут быть ежедневными сборками, в основном используются для тестирования в определенных ситуациях, ознакомления с новыми функциями и получения обратной связи для дальнейшего улучшения.</li><li>Стабильные версии выпускаются по расписанию (например, ежемесячно) и содержат стабильные изменения.</li></ul></li></ul><h3 id="использование-других-проектов" tabindex="-1">Использование других проектов <a class="header-anchor" href="#использование-других-проектов" aria-label="Permalink to “Использование других проектов”">​</a></h3><ul><li>Golang <ul><li>В коде рекомендуется использовать стандартную библиотеку Golang и библиотеки из <a href="https://pkg.go.dev/search?limit=25&amp;m=package&amp;q=golang.org%2Fx" target="_blank" rel="noreferrer">golang.org/x/</a>.</li><li>Если вам нужно использовать другие проекты, сначала создайте issue для обсуждения.</li></ul></li><li>Другие <ul><li>Можно использовать любые инструменты, которые не нарушают лицензии обеих сторон и полезны для проекта.</li></ul></li></ul><h2 id="процесс-разработки" tabindex="-1">Процесс разработки <a class="header-anchor" href="#процесс-разработки" aria-label="Permalink to “Процесс разработки”">​</a></h2><h3 id="перед-написанием-кода" tabindex="-1">Перед написанием кода <a class="header-anchor" href="#перед-написанием-кода" aria-label="Permalink to “Перед написанием кода”">​</a></h3><p>Если вы обнаружили какую-либо проблему или у вас есть идеи по улучшению проекта, создайте <a href="https://github.com/XTLS/Xray-core/issues" target="_blank" rel="noreferrer">issue</a> для обсуждения, чтобы избежать дублирования усилий и траты времени на написание кода.</p><h3 id="изменение-кода" tabindex="-1">Изменение кода <a class="header-anchor" href="#изменение-кода" aria-label="Permalink to “Изменение кода”">​</a></h3><ul><li>Golang <ul><li>См. <a href="https://golang.org/doc/effective_go.html" target="_blank" rel="noreferrer">Effective Go</a>.</li><li>Перед каждой отправкой (push) выполните команду: <code>go generate core/format.go</code>.</li><li>Если вам нужно изменить protobuf, например, добавить новый параметр конфигурации, выполните команду: <code>go generate core/proto.go</code>.</li><li>Перед отправкой pull request рекомендуется запустить тесты: <code>go test ./...</code>.</li><li>Перед отправкой pull request рекомендуется, чтобы новый код имел покрытие кода (code coverage) не менее 70%.</li></ul></li><li>Другие <ul><li>Обратите внимание на читаемость кода.</li></ul></li></ul><h3 id="запрос-на-включение-изменении-pull-request" tabindex="-1">Запрос на включение изменений (Pull Request) <a class="header-anchor" href="#запрос-на-включение-изменении-pull-request" aria-label="Permalink to “Запрос на включение изменений (Pull Request)”">​</a></h3><ul><li>Перед отправкой PR сначала выполните команду <code>git pull https://github.com/XTLS/Xray-core.git</code>, чтобы убедиться, что слияние пройдет гладко.</li><li>Один PR должен решать только одну задачу. Если вы исправляете несколько ошибок, отправьте по одному PR для каждой ошибки.</li><li>Из-за особенностей Golang (пути к пакетам) процесс PR для проектов Go отличается от других проектов. Рекомендуемый процесс следующий: <ol><li>Сначала сделайте форк (fork) проекта, создайте свой собственный репозиторий <code>github.com/&lt;your_name&gt;/Xray-core.git</code>.</li><li>Клонируйте свой репозиторий Xray локально: <code>git clone https://github.com/&lt;your_name&gt;/Xray-core.git</code>.</li><li>Создайте новую ветку на основе ветки <code>main</code>, например, <code>git branch issue24 main</code>.</li><li>Внесите изменения в новую ветку и зафиксируйте их (commit).</li><li>Перед отправкой (push) измененной ветки в свой репозиторий переключитесь на ветку <code>main</code> и выполните команду <code>git pull https://github.com/XTLS/Xray-core.git</code>, чтобы получить последнюю версию кода.</li><li>Если на предыдущем шаге были получены новые изменения, переключитесь на созданную вами ветку и выполните команду <code>git rebase main</code> для слияния веток. Если возникнут конфликты файлов, их необходимо разрешить.</li><li>После завершения предыдущего шага вы можете отправить свою ветку в свой репозиторий: <code>git push -u origin your-branch</code>.</li><li>Наконец, отправьте PR из своей ветки в ветку <code>main</code> репозитория <code>XTLS/Xray-core</code>.</li><li>В заголовке и описании PR четко опишите проблему, которую решает этот PR / новую функцию / цель изменений кода.</li><li>Дождитесь ответа разработчиков.</li></ol></li></ul><h3 id="изменения-кода" tabindex="-1">Изменения кода <a class="header-anchor" href="#изменения-кода" aria-label="Permalink to “Изменения кода”">​</a></h3><h4 id="проблемы-с-функциональностью" tabindex="-1">Проблемы с функциональностью <a class="header-anchor" href="#проблемы-с-функциональностью" aria-label="Permalink to “Проблемы с функциональностью”">​</a></h4><p>Отправьте хотя бы один тестовый пример (Test Case), чтобы проверить изменения в существующей функциональности.</p><h4 id="проблемы-с-производительностью" tabindex="-1">Проблемы с производительностью <a class="header-anchor" href="#проблемы-с-производительностью" aria-label="Permalink to “Проблемы с производительностью”">​</a></h4><p>Отправьте необходимые тестовые данные, чтобы подтвердить проблемы с производительностью существующего кода или улучшение производительности нового кода.</p><h4 id="новые-функции" tabindex="-1">Новые функции <a class="header-anchor" href="#новые-функции" aria-label="Permalink to “Новые функции”">​</a></h4><ul><li>Если новая функция не влияет на существующую функциональность, предоставьте переключатель (например, флаг) для ее включения/отключения и оставьте ее отключенной по умолчанию.</li><li>Перед разработкой новой крупной функции (например, добавления нового протокола) создайте issue для обсуждения.</li></ul><h4 id="другое" tabindex="-1">Другое <a class="header-anchor" href="#другое" aria-label="Permalink to “Другое”">​</a></h4><p>Зависит от конкретной ситуации.</p><h2 id="стандарты-кодирования-xray" tabindex="-1">Стандарты кодирования Xray <a class="header-anchor" href="#стандарты-кодирования-xray" aria-label="Permalink to “Стандарты кодирования Xray”">​</a></h2><p>Следующие правила применяются к коду Golang в Xray.</p><h3 id="структура-кода" tabindex="-1">Структура кода <a class="header-anchor" href="#структура-кода" aria-label="Permalink to “Структура кода”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span>Xray-core</span></span>
<span class="line"><span>├── app        // Модули приложений</span></span>
<span class="line"><span>│   ├── router // Маршрутизация</span></span>
<span class="line"><span>├── common     // Общий код</span></span>
<span class="line"><span>├── proxy      // Протоколы связи</span></span>
<span class="line"><span>│   ├── blackhole</span></span>
<span class="line"><span>│   ├── dokodemo</span></span>
<span class="line"><span>│   ├── freedom</span></span>
<span class="line"><span>│   ├── socks</span></span>
<span class="line"><span>│   ├── vmess</span></span>
<span class="line"><span>├── transport  // Транспортные модули</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="стандарты-кодирования" tabindex="-1">Стандарты кодирования <a class="header-anchor" href="#стандарты-кодирования" aria-label="Permalink to “Стандарты кодирования”">​</a></h3><p>В основном соответствуют рекомендациям Golang, за некоторыми исключениями. Приведены здесь для удобства ознакомления с Golang.</p><h4 id="именование" tabindex="-1">Именование <a class="header-anchor" href="#именование" aria-label="Permalink to “Именование”">​</a></h4><ul><li>Для имен файлов и каталогов по возможности используйте одно английское слово, например, hello.go. <ul><li>Если это невозможно, используйте дефисы для разделения слов в имени каталога и подчеркивания для разделения слов в имени файла, например, hello-world/hello_again.go.</li><li>Тестовый код должен иметь суффикс _test.go.</li></ul></li><li>Для типов используйте нотацию PascalCase, например, ConnectionHandler. <ul><li>Сокращения не обязательно писать в нижнем регистре, то есть HTML не нужно писать как Html.</li></ul></li><li>Для публичных переменных-членов также используйте нотацию PascalCase.</li><li>Для приватных переменных-членов используйте <a href="https://ru.wikipedia.org/wiki/CamelCase" target="_blank" rel="noreferrer">нотацию camelCase</a>, например, <code>privateAttribute</code>.</li><li>Для удобства рефакторинга рекомендуется использовать нотацию PascalCase для всех методов. <ul><li>Полностью приватные типы помещайте в каталог <code>internal</code>.</li></ul></li></ul><h4 id="организация-кода" tabindex="-1">Организация кода <a class="header-anchor" href="#организация-кода" aria-label="Permalink to “Организация кода”">​</a></h4><ul><li>Один файл должен содержать один основной тип и связанные с ним приватные функции.</li><li>Тестовые файлы, такие как Mock и другие утилиты, помещайте в подкаталог testing.</li></ul><h4 id="int32range" tabindex="-1">Int32Range <a class="header-anchor" href="#int32range" aria-label="Permalink to “Int32Range”">​</a></h4><p><strong>Для конечного пользователя</strong></p><p>Значение, представляющее собой необязательный диапазон. Возможные варианты записи:</p><ul><li>Отдельное число или диапазон, заключенные в кавычки: <ul><li><code>&quot;&quot;</code> (считается как 0). Обратите внимание, что полное отсутствие настройки поля и установка пустого значения могут иметь разное значение.</li><li><code>&quot;114&quot;</code></li><li><code>&quot;114-514&quot;</code></li></ul></li><li>Отдельное целое число (int). В этом случае возможно указать только одно число: <ul><li><code>114</code></li></ul></li></ul><p><strong>Для разработчика</strong></p><p>Если вам нужно использовать диапазон в файле конфигурации, используйте тип <code>Int32Range</code>.</p><p>Используйте <code>.From</code> и <code>.To</code> для получения значений. Когда From &gt; To (например, 1919-810), значения автоматически меняются местами, чтобы гарантировать, что From меньше To. Если вы хотите получить исходные значения, можно использовать <code>.Left</code> и <code>.Right</code>.</p>`,36)])}var l=i(s,[[`render`,c]]);export{o as __pageData,l as default};